import{_ as a,a0 as l,w as n,s as i,ao as u,I as p,x as e,a1 as r,A as s}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const k=JSON.parse('{"title":"美国立法者提出一项保护开源软件的新法案 | LCTT x X-CMD","titleTemplate":false,"description":"美国立法者提出一项保护开源软件的新法案 | LCTT (202209) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"美国立法者提出一项保护开源软件的新法案 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"美国立法者提出一项保护开源软件的新法案 | LCTT (202209) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202209/20220923 Lawmakers Proposes A New Bill To Protect Open Source Software","title":"美国立法者提出一项保护开源软件的新法案","tag":"202209","desc":""},"relativePath":"202209/20220923 Lawmakers Proposes A New Bill To Protect Open Source Software.md","filePath":"[post].md"}'),m={name:"202209/20220923 Lawmakers Proposes A New Bill To Protect Open Source Software.md"};function w(f,t,d,T,C,S){const o=l("Link");return n(),i("div",null,[t[15]||(t[15]=u('<h1 id="美国立法者提出一项保护开源软件的新法案" tabindex="-1">美国立法者提出一项保护开源软件的新法案 <a class="header-anchor" href="#美国立法者提出一项保护开源软件的新法案" aria-label="Permalink to “美国立法者提出一项保护开源软件的新法案”">​</a></h1><p><img src="https://www.opensourceforu.com/wp-content/uploads/2022/09/law-4-1536x1025.jpeg" alt=""></p><blockquote><p>美国的《保护开源软件法案》将责成管理和预算办公室提供有关如何安全使用开源软件的说明。</p></blockquote><p>美国立法者周四提出了一项要求，美国网络安全和基础设施安全局（CISA）需创建风险框架以提高开源软件安全性的措施。为了降低依赖开源代码的系统风险，各机构将利用该框架，CISA 将决定关键基础设施所有者和运营商是否也可以自愿使用它。</p><p>大多数系统依赖于免费提供的并由社区维护的开源软件来构建网站和应用程序；最大的用户之一是美国联邦政府。该立法由美国国土安全委员会主席兼高级成员、俄亥俄州共和党参议员 Sens. Rob Portman、R-Ohio 和 Gary Peters D-Mich 在一次听证会后提出，以回应在开源代码中发现的影响美国联邦系统和全球数百万其他系统的严重、广泛的 Log4j 漏洞。</p><p>“这一事件对联邦系统和关键基础设施公司——包括银行、医院和公用事业公司——构成了严重威胁，美国人每天都依赖这些公司提供基本服务，”彼得斯在公告中说。“这项明智的两党立法将有助于保护开源软件，并进一步加强我们的网络安全防御，防止网络犯罪分子和外国对手对全国网络发起的不断的攻击。”</p><p>这项《保护开源软件法》还要求美国管理和预算办公室为各机构发布关于保护开源软件的指南，在 CISA 网络安全咨询委员会中设立一个软件安全小组委员会，并要求 CISA 聘请开源软件专家协助处理网络事件。</p><p>在此之前，Peters 和 Portman 的提议已获得美国参议院一致通过并签署成为法律，以加强州和地方政府的网络防御，并迫使关键基础设施的所有者和运营商向 CISA 报告重大网络攻击和勒索软件付款。</p><hr>',9)),p("p",null,[t[1]||(t[1]=e("via: ",-1)),r(o,{href:"https://www.opensourceforu.com/2022/09/lawmakers-proposes-a-new-bill-to-protect-open-source-software/"},{default:s(()=>[...t[0]||(t[0]=[e("https://www.opensourceforu.com/2022/09/lawmakers-proposes-a-new-bill-to-protect-open-source-software/",-1)])]),_:1})]),p("p",null,[t[6]||(t[6]=e("作者：",-1)),r(o,{href:"https://www.opensourceforu.com/author/laveesh-kocher/"},{default:s(()=>[...t[2]||(t[2]=[e("Laveesh Kocher",-1)])]),_:1}),t[7]||(t[7]=e(" 选题：",-1)),r(o,{href:"https://github.com/lkxed"},{default:s(()=>[...t[3]||(t[3]=[e("lkxed",-1)])]),_:1}),t[8]||(t[8]=e(" 译者：",-1)),r(o,{href:"https://github.com/littlebirdnest"},{default:s(()=>[...t[4]||(t[4]=[e("littlebirdnest",-1)])]),_:1}),t[9]||(t[9]=e(" 校对：",-1)),r(o,{href:"https://github.com/wxy"},{default:s(()=>[...t[5]||(t[5]=[e("wxy",-1)])]),_:1})]),p("p",null,[t[12]||(t[12]=e("本文由 ",-1)),r(o,{href:"https://github.com/LCTT/TranslateProject"},{default:s(()=>[...t[10]||(t[10]=[e("LCTT",-1)])]),_:1}),t[13]||(t[13]=e(" 原创编译，",-1)),r(o,{href:"https://linux.cn/"},{default:s(()=>[...t[11]||(t[11]=[e("Linux中国",-1)])]),_:1}),t[14]||(t[14]=e(" 荣誉推出",-1))])])}const L=a(m,[["render",w]]);export{k as __pageData,L as default};
